statement:
Build a list of `n` strings, one for each whole number `i` from `1` to `n` in increasing order (position `i` of the 1-indexed list belongs to `i`). The string for `i` is:

- `"FizzBuzz"` when `i` is a multiple of both 3 and 5;
- otherwise `"Fizz"` when `i` is a multiple of 3;
- otherwise `"Buzz"` when `i` is a multiple of 5;
- otherwise the decimal digits of `i` (for example `"7"`).

Return the list.

validator:
function validate([n]) {
  if (!Number.isInteger(n) || n < 1 || n > 10000) return 'n must be a whole number from 1 to 10000.';
  return null;
}

reference:
function fizzBuzz(n) {
  const answer = [];
  for (let i = 1; i <= n; i++) {
    if (i % 15 === 0) {
      answer.push("FizzBuzz");
    } else if (i % 3 === 0) {
      answer.push("Fizz");
    } else if (i % 5 === 0) {
      answer.push("Buzz");
    } else {
      answer.push(String(i));
    }
  }
  return answer;
}

brute:
function fizzBuzz(n) {
  // Glue the words together, using countdowns instead of the % operator.
  const result = [];
  let three = 3, five = 5;
  for (let i = 1; i <= n; i++) {
    three--; five--;
    let word = '';
    if (three === 0) { word += 'Fizz'; three = 3; }
    if (five === 0) { word += 'Buzz'; five = 5; }
    result.push(word === '' ? `${i}` : word);
  }
  return result;
}

generator:
function generate(rand, size) {
  if (size === 'small') return [1 + Math.floor(rand() * 40)];
  return [rand() < 0.2 ? 10000 : 1000 + Math.floor(rand() * 9001)];
}
